for name,before,after,edits in changes:
    p=Path(name); old=p.read_bytes() if p.exists() else b''
    assert hashlib.sha256(old).hexdigest()==before,(name,'source changed')
    lines=old.decode().splitlines(keepends=True)
    for start,end,text in reversed(edits): lines[start:end]=[text]
    result=''.join(lines).encode()
    assert hashlib.sha256(result).hexdigest()==after,(name,'patch mismatch')
    p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(result)
Path('/tmp/authorities-changed-files.txt').write_text('\n'.join(row[0] for row in changes))
